/**
 * What every section of this CRM actually does — written from the code.
 *
 * The owner asked for something better than a guide. The way to get that was
 * not to write one: 38 agents read the product itself — each section's page
 * component, the interface strings it renders, the API routes it calls — and a
 * second agent per group then tried to DISPROVE every claim, deleting whatever
 * could not be traced to a rendered control, a route or an explicit config.
 * Deletion was an expected outcome, not a failure.
 *
 * That order is the point. This text is spoken to the owner as fact, and a
 * plausible feature that does not exist is worse than a short description,
 * because he will act on it. The same mistake — a confident claim that nothing
 * had checked — is what broke voice twice during this work.
 *
 * All safe menu destinations and their capabilities. Kept short enough to be SPOKEN: file paths
 * and line numbers were stripped, because a sentence that reads well in a code
 * review is unusable in a phone call.
 *
 * Russian only. The agent answers in whichever language the user speaks and
 * translates on the fly; pre-translating would triple the surface that has to
 * stay true to the code, in two languages nobody verified against it.
 */

export type SectionGuide = {
  whatItIs: string
  howItWorks: string
  keyFeatures: string[]
}

